create type public.delivery_zone_result as enum ('ELIGIBLE','OUTSIDE_ZONE','DELIVERY_DISABLED');
create table public.delivery_settings(id boolean primary key default true check(id),restaurant_display_name text not null,restaurant_latitude double precision not null check(restaurant_latitude between -90 and 90),restaurant_longitude double precision not null check(restaurant_longitude between -180 and 180),default_map_zoom numeric(4,1) not null default 14 check(default_map_zoom between 1 and 21),delivery_enabled boolean not null default true,maximum_delivery_radius_km numeric(8,3) not null check(maximum_delivery_radius_km>0),base_delivery_fee integer not null check(base_delivery_fee>=0),free_delivery_threshold integer check(free_delivery_threshold is null or free_delivery_threshold>=0),minimum_delivery_order integer not null default 0 check(minimum_delivery_order>=0),updated_at timestamptz not null default now());
comment on table public.delivery_settings is 'Single ZAYTUN GO settings record. Development coordinates are placeholders, not verified production coordinates.';
create trigger delivery_settings_touch before update on public.delivery_settings for each row execute function public.touch_updated_at();
alter table public.customer_addresses add column pin_confirmed_at timestamptz,add column location_provider text check(location_provider in('mock','yandex')),add column provider_place_id text,add column provider_formatted_address text,add column delivery_distance_km numeric(8,3),add column delivery_zone_result delivery_zone_result;
alter table public.orders add column idempotency_key uuid unique;
create or replace function public.geographic_distance_km(p_lat1 double precision,p_lng1 double precision,p_lat2 double precision,p_lng2 double precision) returns double precision language sql immutable strict set search_path=public as $$select 6371*2*asin(sqrt(power(sin(radians(p_lat2-p_lat1)/2),2)+cos(radians(p_lat1))*cos(radians(p_lat2))*power(sin(radians(p_lng2-p_lng1)/2),2)))$$;
create or replace function public.calculate_delivery_quote(p_latitude double precision,p_longitude double precision,p_subtotal integer,p_order_type order_type) returns jsonb language plpgsql stable security definer set search_path=public as $$declare s delivery_settings;d double precision;fee integer;begin if p_order_type='PICKUP'then return jsonb_build_object('eligible',true,'distanceKm',null,'deliveryFee',0,'zoneResult','ELIGIBLE','minimumOrder',0);end if;if p_latitude is null or p_longitude is null or p_latitude not between -90 and 90 or p_longitude not between -180 and 180 or(p_latitude=0 and p_longitude=0)then raise exception 'INVALID_COORDINATES|Xaritadan to‘g‘ri yetkazish nuqtasini tanlang'using errcode='22023';end if;select*into s from delivery_settings where id=true;if not found then raise exception 'DELIVERY_SETTINGS_UNAVAILABLE|Yetkazish sozlamalari vaqtincha mavjud emas';end if;if not s.delivery_enabled then return jsonb_build_object('eligible',false,'distanceKm',null,'deliveryFee',0,'zoneResult','DELIVERY_DISABLED','minimumOrder',s.minimum_delivery_order,'message','Yetkazib berish vaqtincha o‘chirilgan');end if;d:=geographic_distance_km(s.restaurant_latitude,s.restaurant_longitude,p_latitude,p_longitude);fee:=case when s.free_delivery_threshold is not null and p_subtotal>=s.free_delivery_threshold then 0 else s.base_delivery_fee end;return jsonb_build_object('eligible',d<=s.maximum_delivery_radius_km and p_subtotal>=s.minimum_delivery_order,'distanceKm',round(d::numeric,3),'deliveryFee',fee,'zoneResult',case when d<=s.maximum_delivery_radius_km then 'ELIGIBLE' else 'OUTSIDE_ZONE'end,'minimumOrder',s.minimum_delivery_order,'message',case when d>s.maximum_delivery_radius_km then 'Bu manzil yetkazish hududidan tashqarida'when p_subtotal<s.minimum_delivery_order then format('Yetkazish uchun eng kam buyurtma %s so‘m',s.minimum_delivery_order)end);end$$;
create or replace function public.create_public_order(p_order jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare oid uuid:=coalesce((p_order->>'id')::uuid,gen_random_uuid());ikey uuid:=coalesce((p_order->>'idempotencyKey')::uuid,oid);num text;sub integer;typ order_type:=(p_order->>'type')::order_type;a jsonb:=p_order->'address';i jsonb;q jsonb;existing orders;confidence address_confidence;begin select*into existing from orders where idempotency_key=ikey;if found then return jsonb_build_object('id',existing.id,'number',existing.number,'trackingToken',existing.tracking_token,'deliveryFee',existing.delivery_fee,'total',existing.total);end if;if jsonb_array_length(coalesce(p_order->'items','[]'))=0 then raise exception 'EMPTY_ORDER|Kamida bitta taom kerak';end if;select coalesce(sum((x->>'unitPrice')::integer*(x->>'quantity')::integer),0)into sub from jsonb_array_elements(p_order->'items')x;if typ='DELIVERY'and(coalesce(a->>'district','')=''or coalesce(a->>'street','')=''or coalesce(a->>'house','')=''or(coalesce(a->>'landmark','')=''and coalesce(a->>'deliveryNotes','')=''))then raise exception 'INCOMPLETE_ADDRESS|Yozma yetkazish manzilini to‘liq kiriting';end if;if typ='DELIVERY'and a->>'pinConfirmedAt'is null then raise exception 'PIN_CONFIRMATION_REQUIRED|Yetkazish pinini tasdiqlang';end if;q:=calculate_delivery_quote((a->>'latitude')::double precision,(a->>'longitude')::double precision,sub,typ);if not(q->>'eligible')::boolean then if q->>'zoneResult'='DELIVERY_DISABLED'then raise exception 'DELIVERY_DISABLED|Yetkazib berish vaqtincha o‘chirilgan';elsif sub<(q->>'minimumOrder')::integer then raise exception 'MINIMUM_ORDER_NOT_MET|%',q->>'message';else raise exception 'DELIVERY_OUTSIDE_ZONE|Bu manzil yetkazish hududidan tashqarida';end if;end if;confidence:=case when typ='DELIVERY'and a->>'confidence'='NEEDS_CLARIFICATION'then'NEEDS_CLARIFICATION'::address_confidence when typ='DELIVERY'then'COMPLETE'::address_confidence else null end;num:='ZG-'||lpad(nextval('order_number_seq')::text,4,'0');insert into orders(id,idempotency_key,number,customer_name,primary_phone,secondary_phone,order_type,payment_method,special_instructions,subtotal,delivery_fee)values(oid,ikey,num,trim(p_order#>>'{customer,name}'),trim(p_order#>>'{customer,primaryPhone}'),nullif(trim(p_order#>>'{customer,secondaryPhone}'),''),typ,(p_order->>'paymentMethod')::payment_method,coalesce(p_order->>'specialInstructions',''),sub,(q->>'deliveryFee')::integer);if typ='DELIVERY'then insert into customer_addresses(order_id,district,street,house,entrance,floor,apartment,landmark,delivery_notes,latitude,longitude,confidence,pin_confirmed_at,location_provider,provider_place_id,provider_formatted_address,delivery_distance_km,delivery_zone_result)values(oid,a->>'district',a->>'street',a->>'house',nullif(a->>'entrance',''),nullif(a->>'floor',''),nullif(a->>'apartment',''),coalesce(a->>'landmark',''),coalesce(a->>'deliveryNotes',''),(a->>'latitude')::double precision,(a->>'longitude')::double precision,confidence,(a->>'pinConfirmedAt')::timestamptz,coalesce(a->>'locationProvider','mock'),nullif(a->>'providerPlaceId',''),nullif(a->>'providerFormattedAddress',''),(q->>'distanceKm')::numeric,(q->>'zoneResult')::delivery_zone_result);end if;for i in select*from jsonb_array_elements(p_order->'items')loop insert into order_items(order_id,menu_item_id,name,unit_price,quantity,modifier_ids,modifier_names,instructions)values(oid,nullif(i->>'menuItemId',''),i->>'name',(i->>'unitPrice')::integer,(i->>'quantity')::integer,array(select jsonb_array_elements_text(coalesce(i->'modifierIds','[]'))),array(select jsonb_array_elements_text(coalesce(i->'modifierNames','[]'))),coalesce(i->>'instructions',''));end loop;insert into order_events(order_id,actor_type,actor_id,new_status,notes)values(oid,'CUSTOMER','guest','NEW',format('Pin confirmed via %s',coalesce(a->>'locationProvider','pickup')));return(select jsonb_build_object('id',id,'number',number,'trackingToken',tracking_token,'deliveryFee',delivery_fee,'total',total)from orders where id=oid);end$$;
create or replace function public.create_order(p_order jsonb) returns jsonb language sql security definer set search_path=public as $$select create_public_order(p_order)$$;
alter table delivery_settings enable row level security;create policy delivery_settings_staff_read on delivery_settings for select to authenticated using(is_staff());revoke all on delivery_settings from anon,authenticated;grant select on delivery_settings to authenticated;revoke all on function calculate_delivery_quote(double precision,double precision,integer,order_type),create_public_order(jsonb)from public;grant execute on function calculate_delivery_quote(double precision,double precision,integer,order_type),create_public_order(jsonb)to anon,authenticated;
